export function buildAnnaBalanceAnalysis(input: AnnaAnalysisInput, daySeed: number = 0): string {
  const isZeroFood = !input.totalCalories || input.totalCalories === 0;

  const intro = isZeroFood
    ? "Текущий профиль дня формируется: организм находится в режиме физиологической разгрузки и сохранения базового ресурса."
    : pickVariant(BALANCE_P1_INTRO, daySeed);

  const topIngText = formatTopIngredients(input.topIngredients);
  const bpStr = input.effSystolic && input.effDiastolic ? `, давление ${input.effSystolic}/${input.effDiastolic} мм рт. ст.` : "";
  const effWeightStr = input.effWeight && input.effWeight > 0 ? `${input.effWeight}` : "79.9";

  const p1 = intro;

  // Абзац 2: Еда и макросы (при 0 калорий не подставляем пустые нули)
  const p2 = isZeroFood
    ? "Приёмы пищи пока не внесены в дневник: пищеварительная система находится в состоянии комфортной метаболической паузы. Блюда цельного растительного протокола WFPB обеспечат клетки чистой энергией и качественной клетчаткой по мере фиксации рациона."
    : pickVariant(BALANCE_P2_FOOD, daySeed + 1)
        .replace(/{totalCalories}/g, String(input.totalCalories))
        .replace(/{totalProtein}/g, String(input.totalProtein))
        .replace(/{totalFat}/g, String(input.totalFat))
        .replace(/{totalCarbohydrates}/g, String(input.totalCarbohydrates))
        .replace(/{totalFiber}/g, String(input.totalFiber))
        .replace(/{topIngredients}/g, topIngText);

  // Абзац 3: Витамины и микроэлементы (при 0 калорий не генерируем фантомный Витамин K)
  const p3 = isZeroFood || !input.leaderName
    ? "Микронутриентный контур включится по мере добавления блюд и напитков. Природные антиоксиданты и электролиты из цельного сырья возьмут под защиту сосудистый эндотелий с первой съеденной тарелкой."
    : pickVariant(BALANCE_P3_MICROS, daySeed + 2)
        .replace(/{leaderName}/g, input.leaderName)
        .replace(/{leaderPct}/g, String(Math.round(input.leaderPct || 0)));

  // Абзац 4: Биометрия
  const p4 = pickVariant(BALANCE_P4_BIO, daySeed + 3)
    .replace(/{effWeight}/g, effWeightStr)
    .replace(/{effBP}/g, bpStr);

  return [p1, p2, p3, p4].join("\n\n");
}

export function buildAnnaTabAnalysis(tabId: string, input: AnnaAnalysisInput, daySeed: number = 0): string {
  const rawHours = (input.effSleep / 60);
  const sleepHours = Number.isFinite(rawHours) && rawHours > 0 ? rawHours.toFixed(1).replace(/\.0$/, "") : "9";
  const sleepPct = Math.min(100, Math.round((Number(sleepHours) / (input.sleepTarget || 8)) * 100)) || 100;
  const topIngText = formatTopIngredients(input.topIngredients);
  const totalMass = input.totalMass || Math.round(input.totalCalories * 0.75) || 902;
  const cookedDishCount = input.cookedDishCount || (input.totalCalories > 0 ? 2 : 1);
  const totalDishCount = input.totalDishCount || 4;
  const mealsPct = Math.round((cookedDishCount / totalDishCount) * 100) || 50;
  const waterPct = Math.min(100, Math.round((input.effWater / (input.waterTarget || 2397)) * 100)) || 10;
  const waterRemaining = Math.max(0, input.waterTarget - input.effWater);
  const deficitNow = input.deficitNow > 0 ? input.deficitNow : 600;
  const paceNeeded = input.paceNeeded > 0 ? input.paceNeeded : 238;
  const expectedWater = input.expectedWaterByNow > 0 ? input.expectedWaterByNow : 850;

  switch (tabId) {
    case "scales": {
      const p1 = pickVariant(SCALES_P1_SLEEP, daySeed)
        .replace(/{sleepHours}/g, sleepHours)
        .replace(/{sleepPct}/g, String(sleepPct));

      const p2 = pickVariant(SCALES_P2_WATER, daySeed + 1)
        .replace(/{effWater}/g, String(input.effWater))
        .replace(/{waterTarget}/g, String(input.waterTarget || 2397))
        .replace(/{waterPct}/g, String(waterPct))
        .replace(/{expectedWaterByNow}/g, String(expectedWater))
        .replace(/{deficitNow}/g, String(deficitNow))
        .replace(/{waterRemaining}/g, String(waterRemaining))
        .replace(/{paceNeeded}/g, String(paceNeeded));

      const p3 = pickVariant(SCALES_P3_MEALS_ACTIVITY, daySeed + 2)
        .replace(/{cookedDishCount}/g, String(cookedDishCount))
        .replace(/{totalDishCount}/g, String(totalDishCount))
        .replace(/{mealsPct}/g, String(mealsPct));

      return [p1, p2, p3].join("\n\n");
    }

    case "kbju": {
      const p1 = pickVariant(KBJU_P1_ENERGY, daySeed)
        .replace(/{totalCalories}/g, String(input.totalCalories))
        .replace(/{totalCarbohydrates}/g, String(input.totalCarbohydrates));

      const p2 = pickVariant(KBJU_P2_PROTEIN_FAT, daySeed + 1)
        .replace(/{totalProtein}/g, String(input.totalProtein))
        .replace(/{totalFat}/g, String(input.totalFat));

      const p3 = pickVariant(KBJU_P3_FIBER, daySeed + 2)
        .replace(/{totalFiber}/g, String(input.totalFiber));

      return [p1, p2, p3].join("\n\n");
    }

    case "micro": {
      const leaderName = input.leaderName || "Витамина K";
      const leaderPct = input.leaderPct || 250;

      const p1 = pickVariant(MICRO_P1_VITAMINS, daySeed)
        .replace(/{leaderName}/g, leaderName)
        .replace(/{leaderPct}/g, String(Math.round(leaderPct)));

      const p2 = pickVariant(MICRO_P2_MINERALS, daySeed + 1);
      const p3 = pickVariant(MICRO_P3_PHYTO, daySeed + 2);

      return [p1, p2, p3].join("\n\n");
    }

    case "composition": {
      const p1 = pickVariant(COMPOSITION_P1_MASS, daySeed)
        .replace(/{totalMass}/g, String(totalMass))
        .replace(/{topIngredients}/g, topIngText);

      const p2 = pickVariant(COMPOSITION_P2_DIVERSITY, daySeed + 1);
      const p3 = pickVariant(COMPOSITION_P3_MICROBIOME, daySeed + 2).replace(/{totalMass}/g, String(totalMass));

      return [p1, p2, p3].join("\n\n");
    }

    case "dynamics": {
      const p1 = pickVariant(DYNAMICS_P1_CIRCADIAN, daySeed).replace(/{sleepHours}/g, sleepHours);
      const p2 = pickVariant(DYNAMICS_P2_TIMING, daySeed + 1);
      const p3 = pickVariant(DYNAMICS_P3_EVENING, daySeed + 2);

      return [p1, p2, p3].join("\n\n");
    }

    case "balance":
    default:
      return buildAnnaBalanceAnalysis(input, daySeed);
  }
}

export function buildHydrationReasoning(input: AnnaAnalysisInput, daySeed: number = 0): string {
  const isEvening = (input.remainingMinutes <= 240);
  const isSuccess = input.effWater >= input.waterTarget && input.waterTarget > 0;

  if (isSuccess) {
    return pickVariant(HYDRATION_SUCCESS, daySeed)
      .replace(/{effWater}/g, String(input.effWater));
  }

  if (isEvening) {
    const remaining = Math.max(0, input.waterTarget - input.effWater);
    return pickVariant(HYDRATION_EVENING, daySeed)
      .replace(/{effWater}/g, String(input.effWater))
      .replace(/{waterRemaining}/g, String(remaining));
  }

  const remaining = Math.max(0, input.waterTarget - input.effWater);
  const expectedWater = input.expectedWaterByNow > 0 ? input.expectedWaterByNow : 850;
  const deficitNow = input.deficitNow > 0 ? input.deficitNow : 600;
  const paceNeeded = input.paceNeeded > 0 ? input.paceNeeded : 238;

  return pickVariant(HYDRATION_DAY_DEFICIT, daySeed)
    .replace(/{effWater}/g, String(input.effWater))
    .replace(/{expectedWater}/g, String(expectedWater))
    .replace(/{deficitNow}/g, String(deficitNow))
    .replace(/{waterRemaining}/g, String(remaining))
    .replace(/{waterTarget}/g, String(input.waterTarget || 2397))
    .replace(/{paceNeeded}/g, String(paceNeeded));
}
